// Helper to get numeric value from a series
function getValue(series) {
  if (!series || !series.fields) return null;
  for (const field of series.fields) {
    if (field.type === 'number' && field.values && field.values.length > 0) {
      const val = field.values[field.values.length - 1];
      if (typeof val === 'number' && !isNaN(val)) return val;
    }
  }
  return null;
}

let current = 0, minVal = 0, maxVal = 10000;
const series = context.panel.data.series;

if (series.length >= 1) current = getValue(series[0]) || 0;
if (series.length >= 2) minVal = getValue(series[1]) || 0;
if (series.length >= 3) maxVal = getValue(series[2]) || 10000;

// Ensure max is greater than min
if (maxVal <= minVal) maxVal = minVal + 1000;

// Convert to percentages for arc coloring
const minPct = minVal / 10000;
const maxPct = maxVal / 10000;

return {
  series: [{
    type: 'gauge',
    min: 0,
    max: 10000,
    splitNumber: 10,
    radius: '85%',
    axisLine: {
      lineStyle: {
        width: 20,
        color: [
          [minPct, '#1a1a2e'],
          [maxPct, '#00b4d8'],
          [1, '#1a1a2e']
        ]
      }
    },
    pointer: {
      icon: 'triangle',
      length: '70%',
      width: 8,
      itemStyle: { color: '#ffffff' }
    },
    anchor: {
      show: true,
      showAbove: true,
      size: 18,
      itemStyle: { borderWidth: 2, borderColor: '#999' }
    },
    axisTick: {
      distance: -25,
      length: 8,
      lineStyle: { color: '#999', width: 1 }
    },
    splitLine: {
      distance: -30,
      length: 14,
      lineStyle: { color: '#999', width: 2 }
    },
    axisLabel: {
      color: '#aaa',
      distance: -40,
      fontSize: 14,
      formatter: function(value) {
        if (value === 0) return '0';
        if (value === 10000) return '10k';
        return '';
      }
    },
    detail: {
      valueAnimation: true,
      formatter: function(value) {
        return Math.round(value) + ' W';
      },
      color: '#fff',
      fontSize: 28,
      offsetCenter: [0, '70%']
    },
    data: [{ value: current }]
  }]
};
